#include <stdlib.h>
static int dfs(int**a,int m,int n,int r,int c,int**memo){if(memo[r][c])return memo[r][c];int d[5]={1,0,-1,0,1},b=1;for(int k=0;k<4;k++){int x=r+d[k],y=c+d[k+1];if(x>=0&&y>=0&&x<m&&y<n&&a[x][y]>a[r][c]){int v=1+dfs(a,m,n,x,y,memo);if(v>b)b=v;}}return memo[r][c]=b;}int longestIncreasingPath(int**a,int m,int*cols){if(!m)return 0;int n=cols[0],**memo=malloc(m*sizeof(int*)),best=0;for(int i=0;i<m;i++)memo[i]=calloc(n,sizeof(int));for(int i=0;i<m;i++)for(int j=0;j<n;j++){int v=dfs(a,m,n,i,j,memo);if(v>best)best=v;}for(int i=0;i<m;i++)free(memo[i]);free(memo);return best;}
